destination_or_callback:
()=>{
      const [id,status]=b.dataset.reportState.split('|');const report=state.reports.find(x=>x.id===id);if(!report)return;
      report.status=status;report.history=report.history||[];report.history.push({state:status,at:new Date().toISOString(),note:'Local owner preview state change.'});
      if(persist('report state changed'))renderWorkspace('owner')
    }

()=>{
    const syllabus=document.getElementById('setupSyllabus')?.files?.[0];const schedule=document.getElementById('setupSchedule')?.files?.[0];
    state.instructorClassSetups[chosen.id]={cohort:document.getElementById('setupCohort').value.trim(),section:document.getElementById('setupSection').value.trim(),days:[...document.querySelectorAll('input[name="setupDay"]:checked')].map(x=>x.value),startTime:document.getElementById('setupStartTime').value,endTime:document.getElementById('setupEndTime').value,location:document.getElementById('setupLocation').value.trim(),syllabusName:syllabus?.name||classSetup.syllabusName||'',scheduleName:schedule?.name||classSetup.scheduleName||'',updatedAt:new Date().toISOString()};
    persist('class setup saved');showToast('Class setup saved locally.');renderInstructorWorkspace(chosen.id,'overview')
  }

()=>{
    const qid=document.getElementById('draftQuestion').value;const note=document.getElementById('draftNote').value.trim();
    state.questionDrafts[qid]={note,updatedAt:new Date().toISOString(),sectionId:chosen.id};
    if(persist('question draft note saved')){showToast('Edit note saved locally. The student question was not changed.');renderInstructorWorkspace(chosen.id,'study')}
  }

e=>{
    e.preventDefault();const sectionIds=[...document.querySelectorAll('input[name="announceSection"]:checked')].map(x=>x.value);
    const body=document.getElementById('announcementBody').value.trim();if(!body||!sectionIds.length)return;
    state.announcements.push({id:'ann-'+Date.now(),courseId:chosen.courseId,title:document.getElementById('announcementTitle').value.trim()||'Class update',body,sectionIds,createdAt:new Date().toISOString(),mode:'local-preview'});
    if(persist('announcement saved locally')){showToast('Announcement added to the local preview. Nothing was sent.');renderInstructorWorkspace(chosen.id,'announcements')}
  }

e=>{
    e.preventDefault();const title=document.getElementById('rewardTitle').value.trim();if(!title)return;
    state.teacherRewards.push({id:'reward-'+Date.now(),classId:chosen.id,title,milestone:document.getElementById('rewardMilestone').value.trim(),status:'draft',createdAt:new Date().toISOString()});
    if(persist('teacher achievement draft saved')){showToast('Achievement saved as a local draft.');renderInstructorWorkspace(chosen.id,'rewards')}
  }

e=>{
    e.preventDefault();const file=document.getElementById('teacherSourceFile').files[0],noteId=document.getElementById('teacherSourceClass')?.value||'';
    state.instructorSourceRecords.push({id:'source-'+Date.now(),courseId:chosen.courseId,classId:chosen.id,noteId,title:document.getElementById('teacherSourceTitle').value.trim(),sourceType:document.getElementById('teacherSourceType')?.value||'Other',fileName:file?.name||'',scope:document.getElementById('teacherSourceScope').value,locator:document.getElementById('teacherSourceLocator').value.trim(),reviewState:'Ready for instructor review',publishState:'draft',uploaderRole:'instructor',authorityLabel:'Instructor provided',createdAt:new Date().toISOString()});
    if(persist('source record saved locally')){showToast('Review draft created. Publish only after checking the source.');renderInstructorWorkspace(chosen.id,'sources')}
  }
